INSERT INTO `cd_log` VALUES ('576', 'admin', 'admin', 'http://www.ekqs.com.cn/public/index.php/admin/Service/update', '113.87.234.214', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/103.0.5060.114 Safari/537.36 Edg/103.0.1264.49', '{\"id\":\"6\",\"name\":\"经络推油\",\"cover\":\"https:\\/\\/nianerge.oss-cn-beijing.aliyuncs.com\\/admin\\/202207\\/202207191634160113199.png\",\"banner\":[{\"url\":\"https:\\/\\/nianerge.oss-cn-beijing.aliyuncs.com\\/admin\\/202207\\/202207191634160113199.png\",\"name\":\"meridian_pushing_oil.png\"}],\"sales\":\"0\",\"update_time\":\"1658220493\",\"sort\":\"2\",\"praise\":\"0\",\"show\":\"1\",\"original_price\":\"438\",\"price\":\"418\",\"discount\":\"0\",\"duration\":\"120\",\"label\":[],\"explain\":[{\"id\":\"15\",\"service_id\":\"6\",\"name\":\"\",\"content\":\"推拿手法的注意事项与禁忌：\\na、各种急性传染病，如肝炎、肺结核等；\\nb、各种感染性疾病，如骨髓炎、化脓性关节炎、脑脓肿等；\\nc、某些急性损伤，如脑或中枢神经的损伤、内脏的挫裂伤、骨折早期、截瘫初期、皮肤破裂等；\\nd、诊断不明者，如骨折、骨裂、颈椎脱位、急性脊柱损伤，尤其伴有脊髓症状者，在明确诊断之前，不要轻易施以推拿；\\ne、某些严重疾病，如心脏病、肝病、恶性肿瘤、脓毒血症等；\\nf、某些急腹症，如胃、十二指肠等急性穿孔；\\ng、各种出血症，如外伤出血、便血、尿血等；\\nh、烧伤、烫伤及溃疡性皮炎的局部；\\ni、孕妇的腹部、腰骶部及臀部均禁用推拿；\\nj、妇女月经期间小腹部及腰骶部不宜或慎用推拿；\\n不能安静的精神病、年老体弱、久病体虚、过饥过饱、醉酒者，不宜推拿。\",\"create_time\":\"1658220493\"}]}', null, '1658300535', '2', null);
INSERT INTO `cd_log` VALUES ('577', 'admin', 'admin', 'http://www.ekqs.com.cn/public/index.php/admin/Service/update', '113.87.234.214', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/103.0.5060.114 Safari/537.36 Edg/103.0.1264.49', '{\"id\":\"5\",\"name\":\"睡眠调理\",\"cover\":\"https:\\/\\/nianerge.oss-cn-beijing.aliyuncs.com\\/admin\\/202207\\/202207191632080188042.png\",\"banner\":[{\"url\":\"https:\\/\\/nianerge.oss-cn-beijing.aliyuncs.com\\/admin\\/202207\\/202207191632080188042.png\",\"name\":\"sleep-conditioning.png\"}],\"sales\":\"2\",\"introduce\":\"<pre>睡眠调理是通过手法按摩特定穴位，已到达改善睡眠和促进睡眠的效果<\\/pre><hr\\/><p><span style=\\\"font-size: 1em;\\\">项目流程：头部按摩30分钟<\\/span><\\/p><hr\\/>\",\"update_time\":\"1658219789\",\"sort\":\"3\",\"praise\":\"0\",\"show\":\"1\",\"original_price\":\"198\",\"price\":\"178\",\"discount\":\"0\",\"duration\":\"60\",\"label\":[],\"explain\":[{\"id\":\"16\",\"service_id\":\"5\",\"name\":\"\",\"content\":\"推拿手法的注意事项与禁忌\\na、各种急性传染病，如肝炎、肺结核等；\\nb、各种感染性疾病，如骨髓炎、化脓性关节炎、脑脓肿等；\\nc、某些急性损伤，如脑或中枢神经的损伤、内脏的挫裂伤、骨折早期、截瘫初期、皮肤破裂等；\\nd、诊断不明者，如骨折、骨裂、颈椎脱位、急性脊柱损伤，尤其伴有脊髓症状者，在明确诊断之前，不要轻易施以推拿；\\ne、某些严重疾病，如心脏病、肝病、恶性肿瘤、脓毒血症等；\\nf、某些急腹症，如胃、十二指肠等急性穿孔；\\ng、各种出血症，如外伤出血、便血、尿血等；\\nh、烧伤、烫伤及溃疡性皮炎的局部；\\ni、孕妇的腹部、腰骶部及臀部均禁用推拿；\\nj、妇女月经期间小腹部及腰骶部不宜或慎用推拿；\\n不能安静的精神病、年老体弱、久病体虚、过饥过饱、醉酒者，不宜推拿。\",\"create_time\":\"1658219789\"}]}', null, '1658300545', '2', null);
