INSERT INTO `cd_log` VALUES ('678', 'admin', 'admin', 'http://www.ekqs.com.cn/public/index.php/admin/Service/update', '61.144.189.145', 'Mozilla/5.0 (Windows NT 10.0; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/86.0.4240.198 Safari/537.36', '{\"id\":\"5\",\"name\":\"睡眠调理\",\"cover\":\"https:\\/\\/nianerge.oss-cn-beijing.aliyuncs.com\\/admin\\/202207\\/202207191632080188042.png\",\"banner\":[],\"sales\":\"2\",\"introduce\":\"<pre>睡眠调理是通过手法按摩特定穴位，已到达改善睡眠和促进睡眠的效果<\\/pre><hr\\/><p><span style=\\\"font-size: 1em;\\\">项目流程：头部按摩30分钟<\\/span><\\/p><hr\\/>\",\"update_time\":\"1658300938\",\"sort\":\"3\",\"praise\":\"0\",\"show\":\"1\",\"original_price\":\"198\",\"price\":\"178\",\"discount\":\"0\",\"duration\":\"60\",\"label\":[],\"explain\":[{\"id\":\"16\",\"service_id\":\"5\",\"name\":\"注意事项与禁忌：\",\"content\":\"a、各种急性传染病，如肝炎、肺结核等；\\nb、各种感染性疾病，如骨髓炎、化脓性关节炎、脑脓肿等；\\nc、某些急性损伤，如脑或中枢神经的损伤、内脏的挫裂伤、骨折早期、截瘫初期、皮肤破裂等；\\nd、诊断不明者，如骨折、骨裂、颈椎脱位、急性脊柱损伤，尤其伴有脊髓症状者，在明确诊断之前，不要轻易施以推拿；\\ne、某些严重疾病，如心脏病、肝病、恶性肿瘤、脓毒血症等；\\nf、某些急腹症，如胃、十二指肠等急性穿孔；\\ng、各种出血症，如外伤出血、便血、尿血等；\\nh、烧伤、烫伤及溃疡性皮炎的局部；\\ni、孕妇的腹部、腰骶部及臀部均禁用推拿；\\nj、妇女月经期间小腹部及腰骶部不宜或慎用推拿；\\n不能安静的精神病、年老体弱、久病体虚、过饥过饱、醉酒者，不宜推拿。\",\"create_time\":\"1658300938\"}]}', null, '1658994532', '2', null);
INSERT INTO `cd_log` VALUES ('679', 'admin', 'admin', 'http://www.ekqs.com.cn/public/index.php/admin/Service/update', '61.144.189.145', 'Mozilla/5.0 (Windows NT 10.0; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/86.0.4240.198 Safari/537.36', '{\"id\":\"5\",\"name\":\"睡眠调理\",\"cover\":\"https:\\/\\/nianerge.oss-cn-beijing.aliyuncs.com\\/admin\\/202207\\/202207191632080188042.png\",\"banner\":[{\"url\":\"https:\\/\\/nianerge.oss-cn-beijing.aliyuncs.com\\/admin\\/202207\\/202207281548520149656.png\",\"name\":\"睡眠调理.png\"}],\"sales\":\"2\",\"introduce\":\"<pre>睡眠调理是通过手法按摩特定穴位，已到达改善睡眠和促进睡眠的效果<\\/pre><hr\\/><p><span style=\\\"font-size: 1em;\\\">项目流程：头部按摩30分钟<\\/span><\\/p><hr\\/>\",\"update_time\":\"1658994532\",\"sort\":\"3\",\"praise\":\"0\",\"show\":\"1\",\"original_price\":\"198\",\"price\":\"178\",\"discount\":\"0\",\"duration\":\"60\",\"label\":[],\"explain\":[{\"id\":\"16\",\"service_id\":\"5\",\"name\":\"注意事项与禁忌：\",\"content\":\"a、各种急性传染病，如肝炎、肺结核等；\\nb、各种感染性疾病，如骨髓炎、化脓性关节炎、脑脓肿等；\\nc、某些急性损伤，如脑或中枢神经的损伤、内脏的挫裂伤、骨折早期、截瘫初期、皮肤破裂等；\\nd、诊断不明者，如骨折、骨裂、颈椎脱位、急性脊柱损伤，尤其伴有脊髓症状者，在明确诊断之前，不要轻易施以推拿；\\ne、某些严重疾病，如心脏病、肝病、恶性肿瘤、脓毒血症等；\\nf、某些急腹症，如胃、十二指肠等急性穿孔；\\ng、各种出血症，如外伤出血、便血、尿血等；\\nh、烧伤、烫伤及溃疡性皮炎的局部；\\ni、孕妇的腹部、腰骶部及臀部均禁用推拿；\\nj、妇女月经期间小腹部及腰骶部不宜或慎用推拿；\\n不能安静的精神病、年老体弱、久病体虚、过饥过饱、醉酒者，不宜推拿。\",\"create_time\":\"1658994532\"}]}', null, '1658994558', '2', null);
