INSERT INTO `cd_log` VALUES ('1141', 'admin', 'admin', 'https://www.ekqs.com.cn/public/index.php/admin/Service/update', '61.144.189.145', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/104.0.0.0 Safari/537.36', '{\"id\":\"4\",\"name\":\"中医推拿\",\"cover\":\"https:\\/\\/nianerge.oss-cn-beijing.aliyuncs.com\\/admin\\/202207\\/202207281527260157693.png\",\"banner\":[{\"url\":\"https:\\/\\/nianerge.oss-cn-beijing.aliyuncs.com\\/admin\\/202207\\/202207281541030155184.png\",\"name\":\"中医推拿.png\"}],\"sales\":\"21\",\"introduce\":\" <p><img src=\\\"https:\\/\\/ekqs.oss-cn-hangzhou.aliyuncs.com\\/admin\\/202208\\/202208291412080146637.png\\\" style=\\\"max-width:100%;\\\"\\/><br\\/><\\/p>\",\"update_time\":\"1660042169\",\"sort\":\"1\",\"praise\":\"0\",\"show\":\"1\",\"original_price\":\"248\",\"price\":\"228\",\"discount\":\"0\",\"duration\":\"60\",\"label\":[\"生理调理\",\"经络调整\"],\"explain\":[{\"id\":\"17\",\"service_id\":\"4\",\"name\":\"注意事项与禁忌：\",\"content\":\"a、各种急性传染病，如肝炎、肺结核等；\\nb、各种感染性疾病，如骨髓炎、化脓性关节炎、脑脓肿等；\\nc、某些急性损伤，如脑或中枢神经的损伤、内脏的挫裂伤、骨折早期、截瘫初期、皮肤破裂等；\\nd、诊断不明者，如骨折、骨裂、颈椎脱位、急性脊柱损伤，尤其伴有脊髓症状者，在明确诊断之前，不要轻易施以推拿；\\ne、某些严重疾病，如心脏病、肝病、恶性肿瘤、脓毒血症等；\\nf、某些急腹症，如胃、十二指肠等急性穿孔；\\ng、各种出血症，如外伤出血、便血、尿血等；\\nh、烧伤、烫伤及溃疡性皮炎的局部；\\ni、孕妇的腹部、腰骶部及臀部均禁用推拿；\\nj、妇女月经期间小腹部及腰骶部不宜或慎用推拿；\\n不能安静的精神病、年老体弱、久病体虚、过饥过饱、醉酒者，不宜推拿。\",\"create_time\":\"1660042170\"}]}', null, '1661753557', '2', null);
