INSERT INTO `cd_log` VALUES ('1319', 'admin', 'admin', 'http://175.178.72.131:3305/public/index.php/admin/Service/update', '183.135.1.14', 'Mozilla/5.0 (Macintosh; Intel Mac OS X 10_13_6) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/105.0.0.0 Safari/537.36', '{\"id\":\"16\",\"name\":\"少儿推拿\",\"cover\":\"https:\\/\\/ekqs.oss-cn-hangzhou.aliyuncs.com\\/admin\\/202208\\/202208261826390176439.png\",\"banner\":[{\"url\":\"https:\\/\\/ekqs.oss-cn-hangzhou.aliyuncs.com\\/admin\\/202208\\/202208311202570180402.gif\",\"name\":\"4.gif\"}],\"sales\":\"1004\",\"introduce\":\"<p><img src=\\\"https:\\/\\/nianerge.oss-cn-beijing.aliyuncs.com\\/admin\\/202208\\/202208120942460161068.jpg\\\" style=\\\"font-size: 16px; max-width: 100%;\\\"\\/><br\\/><\\/p>\",\"update_time\":\"1663901079\",\"sort\":\"9\",\"praise\":\"9.9\",\"show\":\"1\",\"original_price\":\"500\",\"price\":\"352\",\"discount\":\"6\",\"duration\":\"120\",\"label\":[\"调理生机\",\"促进成长\"],\"explain\":[{\"name\":\"下单须知\",\"content\":\"1．如客户选择理疗师下单后，理疗师与该客户联系确定了服务时间、服务地址，理疗师按了出发，客户要取消订单的，该客户所付理疗师的交通费用不予退还。\\n2．理疗师到达服务地址后若联系不上客户，理疗师会等待20分钟；如20分钟后仍无法联系上，理疗师则会自行离开，并且该笔订单会自动取消，同时需扣除订单包含的车费和一半项目费。\\n3．客户选择公交／地铁下单的（包含1km免车费），理疗师出发10分钟内取消订单的扣取车费和20元空单费；出发10分钟后取消订单扣车费和一半项目费。\\n4．客户选择滴滴／出租车下单的，需收取来回车费，理疗师未按出发的费用全额退还给客户，已按出发的将支付相应的车费作为空单费。\\n5．客户无论选择公交／滴滴／出租车任一出行方式进行下单，若理\\n疗师已到达服务地址，客户取消订单，需扣除车费和一半项目费用，感谢您的支持和理解。\"}]}', null, '1664953991', '2', null);
