INSERT INTO `cd_log` VALUES ('1368', 'admin', 'admin', 'http://175.178.72.131:3305/public/index.php/admin/Service/update', '60.179.64.23', 'Mozilla/5.0 (Windows NT 6.1; WOW64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/86.0.4240.198 Safari/537.36', '{\"id\":\"8\",\"name\":\"泰式按摩\",\"cover\":\"https:\\/\\/ekqs.oss-cn-hangzhou.aliyuncs.com\\/admin\\/202210\\/202210060940350187665.jpg\",\"banner\":[{\"url\":\"https:\\/\\/ekqs.oss-cn-hangzhou.aliyuncs.com\\/admin\\/202210\\/202210060940350187665.jpg\",\"name\":\"泰式2.jpg\"}],\"sales\":\"14\",\"update_time\":\"1665049235\",\"sort\":\"5\",\"praise\":\"0\",\"show\":\"1\",\"original_price\":\"318\",\"price\":\"239\",\"discount\":\"0\",\"duration\":\"60\",\"label\":[],\"explain\":[{\"id\":\"3\",\"service_id\":\"8\",\"name\":\"下单须知\",\"content\":\"1．如客户选择理疗师下单后，理疗师与该客户联系确定了服务时间、服务地址，理疗师按了出发，客户要取消订单的，该客户所付理疗师的交通费用不予退还。\\n2．理疗师到达服务地址后若联系不上客户，理疗师会等待20分钟；如20分钟后仍无法联系上，理疗师则会自行离开，并且该笔订单会自动取消，同时需扣除订单包含的车费和一半项目费。\\n3．客户选择公交／地铁下单的（包含1km免车费），理疗师出发10分钟内取消订单的扣取车费和20元空单费；出发10分钟后取消订单扣车费和一半项目费。\\n4．客户选择滴滴／出租车下单的，需收取来回车费，理疗师未按出发的费用全额退还给客户，已按出发的将支付相应的车费作为空单费。\\n5．客户无论选择公交／滴滴／出租车任一出行方式进行下单，若理\\n疗师已到达服务地址，客户取消订单，需扣除车费和一半项目费用，感谢您的支持和理解。\",\"create_time\":\"1665049235\"}]}', null, '1665049542', '2', null);
