-- ----------------------------
-- Table structure for cd_coupon
-- ----------------------------
DROP TABLE IF EXISTS `cd_coupon`;
CREATE TABLE `cd_coupon` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '表id',
  `primary_id` int(11) DEFAULT '0' COMMENT '原优惠券id',
  `name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '名称',
  `exchange` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '兑换码',
  `money` decimal(10,2) DEFAULT NULL COMMENT '余额',
  `discount` decimal(2,1) DEFAULT NULL COMMENT '折扣',
  `condition` decimal(10,2) DEFAULT NULL COMMENT '条件',
  `type` tinyint(1) DEFAULT '0' COMMENT '0满减券；1折扣券',
  `get_type` tinyint(1) DEFAULT '0' COMMENT '0直接领取；1赠送；2兑换',
  `user_id` int(11) DEFAULT '0' COMMENT '用户id',
  `service_id` int(11) DEFAULT '0' COMMENT '服务id',
  `create_time` int(10) unsigned DEFAULT '0' COMMENT '注册时间',
  `start_time` int(10) unsigned DEFAULT '0' COMMENT '起始时间',
  `end_time` int(10) unsigned DEFAULT '0' COMMENT '结束时间',
  `status` tinyint(1) DEFAULT '1' COMMENT '0隐藏；1正常',
  `use` tinyint(1) DEFAULT '0' COMMENT '0未使用；1使用',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=750 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='优惠券';

