-- ----------------------------
-- Table structure for cd_dev_crontab
-- ----------------------------
DROP TABLE IF EXISTS `cd_dev_crontab`;
CREATE TABLE `cd_dev_crontab` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(32) CHARACTER SET utf8mb4 NOT NULL,
  `type` tinyint(1) DEFAULT NULL COMMENT '类型：1-定时任务；2-守护进程',
  `remark` varchar(255) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '备注',
  `command` varchar(64) CHARACTER SET utf8mb4 NOT NULL COMMENT '命令内容',
  `parameter` varchar(64) CHARACTER SET utf8mb4 DEFAULT '' COMMENT '参数',
  `status` tinyint(1) NOT NULL DEFAULT '0' COMMENT '状态：1-运行；2-停止；3-错误；',
  `expression` varchar(64) CHARACTER SET utf8mb4 NOT NULL COMMENT '运行规则',
  `error` varchar(256) CHARACTER SET utf8mb4 DEFAULT NULL COMMENT '运行失败原因',
  `create_time` int(11) DEFAULT NULL COMMENT '创建时间',
  `update_time` int(11) DEFAULT NULL COMMENT '最后执行时间',
  `last_time` int(11) DEFAULT NULL COMMENT '最后执行时间',
  `time` varchar(11) CHARACTER SET utf8mb4 DEFAULT '0' COMMENT '实时执行时长',
  `max_time` varchar(11) CHARACTER SET utf8mb4 DEFAULT '0' COMMENT '最大执行时长',
  `system` tinyint(4) DEFAULT '0' COMMENT '是否系统任务：0-否；1-是；',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COMMENT='定时任务表';

