-- ----------------------------
-- Table structure for cd_order
-- ----------------------------
DROP TABLE IF EXISTS `cd_order`;
CREATE TABLE `cd_order` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '表id',
  `order_sn` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '订单号',
  `pay_money` decimal(10,2) DEFAULT '0.00' COMMENT '支付金额',
  `total_money` decimal(10,2) DEFAULT '0.00' COMMENT '总金额',
  `discount` decimal(10,2) DEFAULT NULL COMMENT '优惠金额',
  `technician_money` decimal(10,2) DEFAULT '0.00' COMMENT '技师收入',
  `order_status` tinyint(1) DEFAULT '0' COMMENT '0待付款；1待确认；2待服务；3进行中;4完成；5评价；6取消订单',
  `pay_status` tinyint(1) DEFAULT '0' COMMENT '0待付款；1支付；2退款',
  `user_id` int(11) DEFAULT '0' COMMENT '用户id',
  `technician_id` int(11) DEFAULT '0' COMMENT '技师id',
  `service_id` int(11) DEFAULT '0' COMMENT '服务id',
  `spec_id` int(11) DEFAULT '0' COMMENT '规格id',
  `coupon_id` int(11) DEFAULT '0' COMMENT '优惠券id',
  `realname` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '姓名',
  `mobile` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '电话',
  `province` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '省',
  `city` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '市',
  `district` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '区',
  `address` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '详细地址',
  `create_time` int(10) unsigned DEFAULT '0' COMMENT '注册时间',
  `appointment_time` int(10) DEFAULT '0' COMMENT '预约时间',
  `duration` int(5) DEFAULT '0' COMMENT '时长',
  `fare` decimal(10,2) DEFAULT NULL COMMENT '车费',
  `refund` decimal(10,2) DEFAULT '0.00' COMMENT '退款金额',
  `payment` tinyint(4) DEFAULT '1' COMMENT '1余额；2微信；3支付宝',
  `brokerage` decimal(10,2) DEFAULT '0.00' COMMENT '佣金',
  `second_brokerage` decimal(10,2) DEFAULT NULL COMMENT '二级佣金',
  `complete_time` int(10) DEFAULT '0' COMMENT '完成时间',
  `cancel_type` tinyint(1) DEFAULT '0' COMMENT '0用户；1技师取消',
  `lat` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '纬度',
  `lng` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '经度',
  `cancel_reason` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '取消原因',
  `receiving_time` int(10) DEFAULT '0' COMMENT '接单时间',
  `service_time` int(11) DEFAULT '0' COMMENT '开始服务时间',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='订单表';

-- ----------------------------
-- Records of cd_order
