-- ----------------------------
-- Table structure for cd_technician
-- ----------------------------
DROP TABLE IF EXISTS `cd_technician`;
CREATE TABLE `cd_technician` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '表id',
  `nickname` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '昵称',
  `username` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户名',
  `realname` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '真名',
  `service` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '服务ids',
  `week` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '周ids',
  `start_time` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务起始时间',
  `end_time` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '服务结束时间',
  `sex` tinyint(1) DEFAULT '2' COMMENT '性别=0保密,1男,2女',
  `openid` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT 'openid',
  `last_login` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '最后登录时间',
  `login_num` int(11) DEFAULT '0' COMMENT '登录次数',
  `last_ip` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '最后登录ip',
  `mobile` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '手机号码',
  `avatar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '头像',
  `album` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '相册',
  `status` tinyint(1) DEFAULT '0' COMMENT '0未认证；1认证',
  `balance` decimal(10,2) DEFAULT '0.00' COMMENT '余额',
  `praise` decimal(2,1) DEFAULT '0.0' COMMENT '好评',
  `credit` int(5) DEFAULT '80' COMMENT '信用',
  `composite` int(5) DEFAULT '5' COMMENT '综合评分',
  `lat` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '纬度',
  `lng` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '经度',
  `create_time` int(10) unsigned DEFAULT '0' COMMENT '注册时间',
  `update_time` int(11) DEFAULT '0',
  `sales` int(11) DEFAULT '0' COMMENT '销量',
  `work_status` tinyint(1) DEFAULT '0' COMMENT '0休息；1工作；2禁用',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签到地址',
  `province` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '省',
  `city` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '市',
  `district` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '区',
  `label` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '标签',
  `unionid` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subscribe` tinyint(1) DEFAULT '0' COMMENT '0未关注公众号',
  `cardsn` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证号码',
  `radius` int(10) DEFAULT '1' COMMENT '服务半径',
  `hframe` int(11) DEFAULT NULL,
  `hrocket` int(11) DEFAULT NULL,
  `hhot` int(11) DEFAULT NULL,
  `fquantity` int(11) DEFAULT '0',
  `tgrade` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='技师';

