CREATE TABLE `cd_technician_identity` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '表id',
  `front` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '正面',
  `back` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '反面',
  `technician_id` int(11) DEFAULT '0' COMMENT '用户id',
  `status` tinyint(1) DEFAULT '1' COMMENT '0未认证；1认证;2拒绝',
  `create_time` int(10) unsigned DEFAULT '0' COMMENT '注册时间',
  `realname` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '姓名',
  `cardsn` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证号码',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='技师身份认证';

-- ----------------------------
-- Records of cd_technician_identity
