CREATE TABLE `cd_technician_qualifications` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '表id',
  `certificates` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '证件照',
  `technician_id` int(11) DEFAULT '0' COMMENT '用户id',
  `status` tinyint(1) DEFAULT '1' COMMENT '0未认证；1认证;2拒绝',
  `create_time` int(10) unsigned DEFAULT '0' COMMENT '注册时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='技师资质认证';

