  `sign` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '签名',
  `technician_id` int(11) DEFAULT '0' COMMENT '用户id',
  `status` tinyint(1) DEFAULT '1' COMMENT '1已签署',
  `create_time` int(10) unsigned DEFAULT '0' COMMENT '签署时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='技师服务协议签署';

