-- ----------------------------
-- Table structure for cd_user
-- ----------------------------
DROP TABLE IF EXISTS `cd_user`;
CREATE TABLE `cd_user` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '表id',
  `pid` int(11) DEFAULT '0' COMMENT '推荐人id',
  `spid` int(11) DEFAULT '0' COMMENT '二级推荐人id',
  `email` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '邮件',
  `nickname` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '昵称',
  `username` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用户名',
  `realname` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '真名',
  `sex` tinyint(1) DEFAULT '0' COMMENT '性别=0保密,1男,2女',
  `password` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '密码',
  `last_login` int(10) unsigned NOT NULL DEFAULT '0' COMMENT '最后登录时间',
  `login_num` int(11) DEFAULT '0' COMMENT '登录次数',
  `last_ip` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '最后登录ip',
  `qq` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT 'QQ',
  `mobile` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '手机号码',
  `avatar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '头像',
  `status` tinyint(1) DEFAULT '1' COMMENT '状态',
  `is_promoter` tinyint(1) DEFAULT '0' COMMENT '1推广人',
  `balance` decimal(10,2) DEFAULT '0.00' COMMENT '余额',
  `brokerage` decimal(10,2) DEFAULT NULL COMMENT '佣金',
  `promo_code` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '推广码',
  `qrcode` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `token` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'token',
  `is_vip` tinyint(1) DEFAULT '0' COMMENT '是否VIP=[0:否,1:是]',
  `overdue_time` int(11) DEFAULT '0' COMMENT '会员到期时间',
  `create_time` int(10) unsigned DEFAULT '0' COMMENT '注册时间',
  `update_time` int(11) DEFAULT '0',
  `delete_time` int(11) DEFAULT '0',
  `apply_time` int(11) DEFAULT '0',
  `praise` decimal(2,1) DEFAULT '0.0' COMMENT '好评率',
  `id_card` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '身份证号',
  `real_status` int(10) NOT NULL DEFAULT '0' COMMENT '实名 0未申请 1审核中 2通过 3驳回',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=341 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='用户表';

-- ----------------------------
-- Records of cd_user
-- ----------------------------

