-- Table structure for cd_user_ali
-- ----------------------------
DROP TABLE IF EXISTS `cd_user_ali`;
CREATE TABLE `cd_user_ali` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '表id',
  `user_id` int(11) DEFAULT '0' COMMENT '用户id',
  `realname` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '姓名',
  `mobile` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '账号',
  `create_time` int(10) unsigned DEFAULT '0' COMMENT '注册时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=COMPACT COMMENT='用户支付宝';

-- ----------------------------
-- Records of cd_user_ali
-- ----------------------------

-- ----------------------------
-- Table structure for cd_user_log
-- ----------------------------
DROP TABLE IF EXISTS `cd_user_log`;
CREATE TABLE `cd_user_log` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '表id',
  `user_id` int(11) DEFAULT '0' COMMENT '用户id',
  `technician_id` int(11) DEFAULT '0' COMMENT '技师id',
  `user_type` tinyint(1) DEFAULT '1' COMMENT '1用户；2技师',
  `order_sn` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单号',
  `money` decimal(10,2) DEFAULT NULL COMMENT '支付金额',
  `type` tinyint(3) DEFAULT '1' COMMENT '1下单；2退款；3会员；4充值；5佣金；6结算；7提现；8提现驳回',
  `income` tinyint(1) DEFAULT '1' COMMENT '1收入；2支出',
  `payment` tinyint(1) DEFAULT '1' COMMENT '1余额；2微信；3支付宝',
  `create_time` int(11) DEFAULT NULL,
  `update_time` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1083 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='财务记录';

-- ----------------------------
-- Records of cd_user_log
-- ----------------------------

-- ----------------------------
-- Table structure for cd_valuation
-- ----------------------------
DROP TABLE IF EXISTS `cd_valuation`;
CREATE TABLE `cd_valuation` (
  `id` mediumint(8) unsigned NOT NULL AUTO_INCREMENT COMMENT '表id',
  `name` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '名称',
  `starting_price` int(11) DEFAULT '0' COMMENT '起步价',
  `average_price` int(11) DEFAULT '0' COMMENT '每公里均价',
  `create_time` int(10) unsigned DEFAULT '0' COMMENT '时间',
  `kilometre` int(3) DEFAULT '0' COMMENT '起步公里',
  `free` int(11) NOT NULL DEFAULT '0' COMMENT '免费距离',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='计价规则';

-- ----------------------------
-- Records of cd_valuation
-- ----------------------------

-- ----------------------------
-- Table structure for cd_withdraw_apply
-- ----------------------------
DROP TABLE IF EXISTS `cd_withdraw_apply`;
CREATE TABLE `cd_withdraw_apply` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `sn` varchar(25) NOT NULL COMMENT '提现单号',
  `user_id` int(11) NOT NULL COMMENT '用户id；技师id',
  `real_name` varchar(255) DEFAULT NULL COMMENT '真实姓名',
  `account` varchar(255) DEFAULT '' COMMENT '账号',
  `type` tinyint(1) NOT NULL COMMENT '类型：\r\n1-提现到钱包余额；\r\n2-提现到微信零钱；\r\n3-提现到微信收款码;\r\n4-提现到支付宝',
  `user_type` tinyint(1) NOT NULL COMMENT '类型：\r\n1-用户；\r\n2-技师',
  `money` decimal(10,2) unsigned NOT NULL COMMENT '提现金额',
  `left_money` decimal(10,2) DEFAULT NULL COMMENT '用户可得的金额(扣除手续费后)',
  `money_qr_code` varchar(128) DEFAULT '' COMMENT '收款二维码',
  `poundage` decimal(10,2) DEFAULT NULL COMMENT '手续费',
  `status` tinyint(1) NOT NULL COMMENT '状态：\r\n1-待提现\r\n2-提现成功\r\n3-提现失败',
  `create_time` int(10) NOT NULL COMMENT '创建时间',
  `update_time` int(10) DEFAULT NULL COMMENT '更新时间',
  `payment_no` varchar(100) DEFAULT NULL COMMENT '支付单号',
  `payment_time` int(11) DEFAULT NULL COMMENT '支付时间',
  `description` varchar(255) DEFAULT NULL COMMENT '审核备注',
  `transfer_voucher` varchar(255) DEFAULT NULL COMMENT '转账凭证',
  `transfer_time` int(11) DEFAULT NULL COMMENT '转账时间',
  `bank` varchar(255) DEFAULT NULL COMMENT '提现银行',
  `subbank` varchar(255) DEFAULT NULL COMMENT '提现银行支行',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT;

-- ----------------------------
-- Records of cd_withdraw_apply
-- ----------------------------
